import{_ as t}from"./chunks/ha-label-erstellen.DlZFuxLI.js";import{_ as a,o as s,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"MQTT-Client","description":"Transfer selected Home Assistant values live over MQTT and control supported entities.","frontmatter":{"title":"MQTT-Client","description":"Transfer selected Home Assistant values live over MQTT and control supported entities."},"headers":[],"relativePath":"en/projects/mqtt-client/index.md","filePath":"en/projects/mqtt-client/index.md","lastUpdated":1794657153000}'),i={name:"en/projects/mqtt-client/index.md"};function o(l,e,d,c,p,h){return s(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="mqtt-client-0-1-16" tabindex="-1">MQTT-Client 0.1.36 <a class="header-anchor" href="#mqtt-client-0-1-16" aria-label="Permalink to &quot;MQTT-Client 0.1.36 {#mqtt-client-0-1-16}&quot;">​</a></h1><p>Forward selected HA states and attributes to an external MQTT broker. MQTT-Client and JavaScript helper 0.1.34 add an optional flat VIS-2 layout with short names. This option requires replacing the complete helper in the ioBroker JavaScript adapter; updating the HA app alone does not replace the script stored there.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.36" target="_blank" rel="noreferrer">Release 0.1.36</a></p><p><strong>App 0.1.35:</strong> A Light selected both manually and by label may temporarily be missing from the HA snapshot without interrupting the selection catalog. The JavaScript helper remains at <strong>0.1.34</strong>.</p><h2 id="settings-persistence-0136" tabindex="-1">New in 0.1.36: retain settings across updates <a class="header-anchor" href="#settings-persistence-0136" aria-label="Permalink to &quot;New in 0.1.36: retain settings across updates {#settings-persistence-0136}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Successful restart test on 7 November 2026</p><p>After saving the settings again when moving to <strong>0.1.36</strong>, the user restarted the MQTT-Client app and confirmed: <strong>The related-measurements checkbox stays enabled and the MQTT layout stays “Flat with short names”.</strong> This confirms the practical restart test. It does not test another version change; a practical update test with the next release is still pending.</p></div><p><strong>Saved app settings now survive the Home Assistant Supervisor regenerating its options file during an update.</strong> This includes the related-measurements checkbox, the MQTT layout for new entities, other saved app settings and credentials. The app stores them independently in its private <code>/data/mqtt-settings.json</code> file. MQTT path assignments remain in <code>/data/mqtt-routes.json</code>; existing points and VIS-2 references are unchanged.</p><p><strong>One-time upgrade from 0.1.35 or earlier:</strong> Export settings in the app before updating. If they have already been reset during the first upgrade, import that backup afterwards or select both options again once and click <strong>Save and connect</strong>. Already lost settings cannot be reliably reconstructed; additional measurements are never enabled without your selection.</p><p>Prefer editing these settings in the app. Actual Supervisor configuration changes are merged on restart; unchanged Supervisor defaults do not reset app choices. To explicitly return an app choice to its default, select and save it in the app. Existing settings backups remain usable and still exclude passwords and private TLS keys. The JavaScript helper remains <strong>0.1.34</strong>; no further helper replacement is required for this fix.</p><p>Background: Supervisor manages <code>/data/options.json</code>; the private <code>/data</code> directory provides persistent storage for the app. <a href="https://contributors.home-assistant.io/apps/reference/environment/" target="_blank" rel="noreferrer">Official HA documentation</a>.</p><h2 id="mqtt-layout-0134" tabindex="-1">New in 0.1.34: flat MQTT paths for new entities only <a class="header-anchor" href="#mqtt-layout-0134" aria-label="Permalink to &quot;New in 0.1.34: flat MQTT paths for new entities only {#mqtt-layout-0134}&quot;">​</a></h2><p>Under <strong>Transmission and TLS → MQTT structure for new entities</strong>, select <strong>Flat with short names</strong> and <strong>Save and connect</strong>. The existing structure remains the default. This preference applies to manually selected entities and label members first encountered afterwards, including optional device measurements.</p><p>Known entities keep their existing paths. Assignments persist in <code>/data/mqtt-routes.json</code> and are included in exported settings backups. Removing and reselecting a label, renaming, restarting or updating reuses the assigned path. On the first upgrade, existing selections and recorded topics are preserved; the existing label selection is pinned during its first successful reconciliation. Do not delete this file. Changing the preference back does not migrate previously assigned entities.</p><p>Example new flat MQTT topics:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ha_external/geraet/schalter</span></span>
<span class="line"><span>ha_external/geraet/schalter_set</span></span>
<span class="line"><span>ha_external/geraet/schalter_attribute/device_class</span></span>
<span class="line"><span>ha_external/geraet/energie</span></span>
<span class="line"><span>ha_external/geraet/leistung</span></span>
<span class="line"><span>ha_external/geraet/licht_brightness</span></span>
<span class="line"><span>ha_external/geraet/licht_brightness_set</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Existing topics such as <code>ha_external/geraet/switch/state</code> and <code>…/switch/set</code> remain valid alongside them. Short-name collisions receive unique suffixes. Existing points, values, aliases and VIS-2 references are neither renamed nor removed.</p><p><strong>Before enabling flat MQTT paths, replace the complete JavaScript helper with 0.1.34 and retain your settings.</strong> It reads both MQTT structures from the published selection catalog with exact state and command paths. Review preview first, then choose <code>mode: &#39;apply&#39;</code>. Older helpers cannot discover new flat MQTT paths. The independent helper option <code>virtualLayout: &#39;flat&#39;</code> only controls the layout below <code>0_userdata.0.ugso_mqtt</code>. Existing manual roles and references remain protected.</p><h2 id="enable-device-readings" tabindex="-1">Important: explicitly enable additional device measurements <a class="header-anchor" href="#enable-device-readings" aria-label="Permalink to &quot;Important: explicitly enable additional device measurements {#enable-device-readings}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Important: explicitly enable additional device measurements</p><p><strong>A label alone does not enable additional measurements.</strong> Under <strong>Transmission and TLS</strong>, check <strong>“Automatically include related measurements and battery values from the same device”</strong> (German UI: <strong>„Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen“</strong>) and then click <strong>“Save and connect”</strong>. Without this checkbox, energy, voltage, current and power are not automatically added to the labeled switch. Manually selected values are independent of this option.</p></div><p>Only supported sensors enabled in HA and associated with the same HA device are included, when available. Measurements not provided by the device are not created. <strong>“Check related measurements”</strong> shows detection and exclusion reasons. Control states have priority; measurements may follow with a delay.</p><h2 id="javascript-vis2-helper" tabindex="-1">Especially for VIS 2: the ioBroker JavaScript helper <a class="header-anchor" href="#javascript-vis2-helper" aria-label="Permalink to &quot;Especially for VIS 2: the ioBroker JavaScript helper {#javascript-vis2-helper}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Especially for VIS 2: the ioBroker JavaScript helper</p><p>The supplied <strong>JavaScript runs in the ioBroker JavaScript adapter, not in Home Assistant</strong>. It creates virtual states under <code>0_userdata.0.ugso_mqtt</code>: <strong>one point per value for display and control</strong>, even though MQTT uses separate <code>state</code> and <code>set</code> topics. Supported switches and light values receive the appropriate command channel; measurements remain read-only. Suitable HA metadata determines data types, units and unambiguous roles. A command is confirmed only after actual HA feedback.</p><p><strong>Review preview first, then set <code>mode: &#39;apply&#39;</code>.</strong> Preview creates only missing helper base folders/backup points; virtual VIS-2 points are created in apply mode. <strong>setObject</strong> must be allowed in the adapter settings for creation. Existing values and manually assigned roles remain protected. The HA app and helper are <strong>0.1.33</strong> for this feature. Replace the complete helper in ioBroker for the flat layout; updating the app alone is insufficient. Plain MQTT forwarding also works without the helper.</p></div><h2 id="new-in-0-1-33-flat-vis-2-layout-with-short-names" tabindex="-1">New in 0.1.33: flat VIS-2 layout with short names <a class="header-anchor" href="#new-in-0-1-33-flat-vis-2-layout-with-short-names" aria-label="Permalink to &quot;New in 0.1.33: flat VIS-2 layout with short names&quot;">​</a></h2><p><strong>Replace the complete JavaScript helper with 0.1.33 and retain your settings.</strong> In its settings block, <code>virtualLayout: &#39;nested&#39;</code> selects the existing layout (default); <code>virtualLayout: &#39;flat&#39;</code> creates short points directly below the device folder, such as <code>schalter</code>, <code>energie</code>, <code>leistung</code>, <code>spannung</code>, <code>stromstaerke</code>. Lights add supported values such as <code>helligkeit</code>, <code>farbe</code>, <code>effekt</code> and <code>farbtemperatur</code>. Duplicate or occupied names receive unique suffixes such as <code>leistung_2</code>; assigned mappings remain pinned in the backup journal.</p><p>Review preview first, then choose <code>mode: &#39;apply&#39;</code>. Switching layout deletes or moves no existing points. Old and new IDs previously created by the helper continue to update and retain their authorized command channels; existing VIS-2 references can stay. Old folders therefore remain visible initially. Unrelated objects and manual roles are not overwritten, and MQTT topics remain unchanged. To switch back, select <code>nested</code> in the new helper; the old 0.1.27 helper cannot read journals containing flat entries.</p><h2 id="new-in-0-1-32-highlight-additional-measurements" tabindex="-1">New in 0.1.32: highlight additional measurements <a class="header-anchor" href="#new-in-0-1-32-highlight-additional-measurements" aria-label="Permalink to &quot;New in 0.1.32: highlight additional measurements&quot;">​</a></h2><p>The <strong>“Automatically include related measurements and battery values from the same device”</strong> option is highlighted in amber. Highlighting does not enable the checkbox: make your selection and click <strong>“Save and connect”</strong>. Existing settings are preserved. TLS and certificates remain separately collapsible.</p><h2 id="new-in-0-1-31-collapse-tls-and-certificates-separately" tabindex="-1">New in 0.1.31: collapse TLS and certificates separately <a class="header-anchor" href="#new-in-0-1-31-collapse-tls-and-certificates-separately" aria-label="Permalink to &quot;New in 0.1.31: collapse TLS and certificates separately&quot;">​</a></h2><p><strong>TLS and certificates</strong> now has its own collapsible section, operable by mouse or keyboard. Its button shows whether TLS is selected even while closed. Expanding/collapsing changes neither TLS nor stored certificates or credentials. The section stays closed after loading and saving; transmission settings and both action buttons remain visible. The <a href="/en/blog/snippets/iobroker-blockly#mqtt-vis2-helper">new JavaScript helper blog entry</a> explains purpose, setup, status/commands and backups and includes the complete unchanged script 0.1.27 with copy button and download.</p><h2 id="new-in-0-1-30-collapsible-credentials" tabindex="-1">New in 0.1.30: collapsible credentials <a class="header-anchor" href="#new-in-0-1-30-collapsible-credentials" aria-label="Permalink to &quot;New in 0.1.30: collapsible credentials&quot;">​</a></h2><p><strong>Credentials</strong> now has a dedicated expand/collapse button with keyboard support. With a configured broker, IP, port, username and password remain collapsed after loading and saving. Missing required credentials open the section for correction. <strong>Transmission and TLS</strong>, <strong>Save and connect</strong> and <strong>Currently transmitted values</strong> stay visible. Settings and credentials are not changed. The 0.1.29 priority logic and helper 0.1.27 are preserved. The user confirmed successful control feedback with a delay of approximately half a second. The Zigbee light was also tested successfully: feedback works and brightness follows HA to 100%.</p><h2 id="new-in-0-1-29-control-states-before-measurements" tabindex="-1">New in 0.1.29: control states before measurements <a class="header-anchor" href="#new-in-0-1-29-control-states-before-measurements" aria-label="Permalink to &quot;New in 0.1.29: control states before measurements&quot;">​</a></h2><p><strong>Update the HA MQTT-Client app to 0.1.29; the ioBroker helper 0.1.27 remains unchanged.</strong> Control/contact states and command feedback take priority over measurements and bypass the configured artificial publish pause. In-flight transmissions finish normally; between messages, measurement/attribute batches yield to urgent states or commands. With at least 32 events waiting, bounded sensor batches collapse intermediate values to the latest state per source. Ordinary control transitions are preserved. A periodic check reads actual HA states even with an active live connection, using the existing <code>poll_interval</code> (default 5 seconds). Unchanged values are not republished. <strong>Übertragung und TLS</strong> and the measurement/attribute publish delay are directly visible; credentials still collapse separately. The status line distinguishes waiting events (<strong>Wartend</strong>), collapsed events (<strong>Zusammengefasst</strong>), the last HA event (<strong>HA-Eingang</strong>) and the cumulative sent count (<strong>Gesendet</strong>). Existing settings and values are preserved. For validation, keep the check interval at 5 seconds and toggle a non-critical relay in HA. Only actual HA feedback produces <code>ack: true</code>; broker handoff is insufficient. Locally verified; end-to-end latency on the user&#39;s system still needs confirmation.</p><p>Switches are recognized by the <code>switch.*</code> domain and require neither a device class nor a unit. Lights use <code>light.*</code>. Enabled automatic measurement selection remains restricted to the same HA device association. Sensors first use <code>device_class</code>; when it is missing, unambiguous <code>unit_of_measurement</code> values such as W/kW/MW, V/mV/kV, A/mA and Wh/kWh/MWh are used. Existing classes are never overridden; similar names or an ambiguous percent sign are insufficient. <strong>Check related measurements</strong> (German UI: <strong>Zugehörige Messwerte prüfen</strong>) provides a read-only report of detected sensors and exclusion reasons, including missing device associations, disabled entities or unsuitable classes/units. Measurements may wait behind control states. Settings, credentials and existing values are preserved.</p><h2 id="new-in-0-1-28-ha-live-feedback-without-unrelated-event-floods" tabindex="-1">New in 0.1.28: HA live feedback without unrelated event floods <a class="header-anchor" href="#new-in-0-1-28-ha-live-feedback-without-unrelated-event-floods" aria-label="Permalink to &quot;New in 0.1.28: HA live feedback without unrelated event floods&quot;">​</a></h2><p>This fix is in the <strong>MQTT-Client app in Home Assistant</strong>: update it to 0.1.28 and restart the app. The ioBroker helper 0.1.27 can remain unchanged; replacing only that script does not fix HA event reception. Label forwarding now queues events only for selected entities and their enabled same-device readings. Events from the rest of HA cannot fill that queue. When labels or device assignments change, the client fetches fresh HA states. Buffered states with an older <code>last_updated</code> are ignored after a resync; normal ordered transitions are preserved. The overload counter is cumulative since app startup and still reports actual selected-event overflows. The configured publish delay, credentials and selections are preserved; a large initial sync may still take longer. After initial sync, toggle a non-critical relay in HA and check that MQTT and the virtual ioBroker state follow promptly. Confirmation on the user&#39;s live system is still pending.</p><h2 id="new-in-0-1-27-return-channel-without-retain" tabindex="-1">New in 0.1.27: return channel without retain <a class="header-anchor" href="#new-in-0-1-27-return-channel-without-retain" aria-label="Permalink to &quot;New in 0.1.27: return channel without retain&quot;">​</a></h2><p>Commands now use the ioBroker MQTT adapter&#39;s <code>sendMessage2Client</code> API with <strong><code>retain: false</code></strong>. Normal writes to MQTT <code>set</code> states may reach the client with RETAIN enabled in server mode. The HA client continues rejecting retained commands so reconnecting cannot execute old requests. Global broker settings and MQTT state values are preserved. The helper validates the command topic against its state topic using <code>native.topic</code>, rather than guessing paths from object IDs. In VIS 2, keep controlling the virtual state below <code>0_userdata.0.ugso_mqtt</code> with <code>ack: false</code> and use <code>mode: &#39;apply&#39;</code>. The log line <code>Command handed to MQTT adapter (retain=false)</code> confirms handoff only; a new HA state is required to confirm execution. The raw MQTT <code>set</code> value need not change. No automatic retry; errors or missing HA feedback remain unconfirmed. Replace the complete helper file while retaining your own settings.</p><h2 id="new-in-0-1-26-automatic-helper-setup" tabindex="-1">New in 0.1.26: automatic helper setup <a class="header-anchor" href="#new-in-0-1-26-automatic-helper-setup" aria-label="Permalink to &quot;New in 0.1.26: automatic helper setup&quot;">​</a></h2><p>Missing helper base folders (<code>virtualRoot</code>, <code>aliasRoot</code>) and both backup states (<code>virtualBackupId</code>, <code>backupId</code>) are now created automatically at startup in <strong>every mode</strong>, including <code>preview</code> and <code>restore</code>. Existing folders, backups, values and manual roles are not overwritten. New journals contain valid empty structures. Allow <code>setObject</code> in the JavaScript instance even for preview. Missing permissions or conflicting paths are reported as errors. Preview does not create controllable VIS-2 states or change MQTT roles or device values; use <code>mode: &#39;apply&#39;</code> after review for those operations. Event-driven processing from 0.1.25 is retained.</p><h2 id="automatic-vis-2-states-since-0-1-24" tabindex="-1">Automatic VIS-2 states since 0.1.24 <a class="header-anchor" href="#automatic-vis-2-states-since-0-1-24" aria-label="Permalink to &quot;Automatic VIS-2 states since 0.1.24&quot;">​</a></h2><p>The combined ioBroker helper creates virtual states combining feedback and a return channel. Supports switches, Light values and other enabled number/select/text channels; dates and measurements remain read-only. Original MQTT values, settings and existing aliases are preserved. Includes preview, automatic backup, type/limit validation and feedback-loop protection. Warnings for missing optional states are fixed. Prepared for JavaScript adapter <strong>10.4.10</strong> APIs; not yet newly tested in a real installation.</p><p><a href="./iobroker-roles#vis2">Setup and mapping table</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.24" target="_blank" rel="noreferrer">Release 0.1.24</a></p><h2 id="iobroker-role-mapping-since-0-1-23" tabindex="-1">ioBroker role mapping since 0.1.23 <a class="header-anchor" href="#iobroker-role-mapping-since-0-1-23" aria-label="Permalink to &quot;ioBroker role mapping since 0.1.23&quot;">​</a></h2><p>An optional JavaScript assigns dates, timestamps and unambiguous measurements to matching ioBroker roles. Includes preview, backup before changes and guarded restore. Existing values, credentials and manual specific roles are preserved. Writable MQTT measurements use read-only aliases. Incompatible types, units and ambiguous classes are skipped.</p><p><a href="./iobroker-roles">Installation and complete HA → ioBroker mapping</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.23" target="_blank" rel="noreferrer">Release 0.1.23</a></p><h2 id="new-in-0-1-22" tabindex="-1">New in 0.1.22 <a class="header-anchor" href="#new-in-0-1-22" aria-label="Permalink to &quot;New in 0.1.22&quot;">​</a></h2><p>Label selection now includes the state, available standard metadata and return channels for supported controllable entities. Switches automatically receive <code>&lt;base&gt;/set</code> for <code>ON</code>/<code>OFF</code>; numbers, selects and buttons use their supported commands. Setup sends no control commands. Retained, empty and invalid commands are discarded.</p><p>Lights receive only channels supported by their HA capabilities:</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Channel below <code>&lt;base&gt;</code></th><th>Value and return channel</th></tr></thead><tbody><tr><td><code>brightness/state</code>, <code>brightness/set</code></td><td>Brightness 0–100%</td></tr><tr><td><code>rgb_color/state</code>, <code>rgb_color/set</code></td><td>JSON <code>[255,128,0]</code>, components 0–255</td></tr><tr><td><code>effect/state</code>, <code>effect/set</code></td><td>Effect name from the reported effect list</td></tr><tr><td><code>color_temp_kelvin/state</code>, <code>color_temp_kelvin/set</code></td><td>Integer Kelvin within the reported limits</td></tr></tbody></table></div><p><code>&lt;base&gt;</code> is the existing topic without <code>/state</code>. Effect lists, supported color modes and minimum/maximum Kelvin values are read-only attributes. Manually selected HA attributes retain their paths and units: <code>attribute/brightness</code> remains 0–255.</p><p>Under <strong>Übertragung und TLS</strong> (Transfer and TLS), enable <strong>Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen</strong> to include related measurements. <code>label_device_readings</code> defaults to <code>false</code>. Supported readings are energy, voltage, current, power, temperature, humidity, battery and an existing battery-low sensor. Matching uses the same HA device ID, never similar names. No thresholds are invented. These additional sensors have no return channels.</p><p>Automatic metadata includes available names, device classes, units and state classes, plus required choices and limits. Other attributes remain selectable manually. <code>device_class</code> is transmitted as metadata; this does not automatically change an ioBroker role such as <code>date</code>.</p><p>The transmission popup also shows automatic attributes, Light values and active return topics with their origin. Removing a label revokes automatic values and return channels at the next sync; queued commands are checked again before execution. Manual selections and credentials are preserved. Old retained values are removed only through confirmed topic cleanup.</p><p>Verified locally with simulated HA and broker; no new HA device test. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.22" target="_blank" rel="noreferrer">Release 0.1.22</a></p><h2 id="current-transmissions" tabindex="-1">Current transmissions <a class="header-anchor" href="#current-transmissions" aria-label="Permalink to &quot;Current transmissions&quot;">​</a></h2><p>Since <strong>0.1.21</strong>, only credentials collapse automatically. <strong>Übertragung und TLS</strong> (Transmission and TLS) remains separately accessible. Equal-size <strong>Save and connect</strong> and <strong>Current transmissions</strong> buttons remain visible in one row.</p><p>The second button opens a searchable, scrollable list of all currently selected states and attributes, including HA-label-selected states. Duplicate states are merged. Labelled origin badges distinguish blue <strong>Label</strong>, green <strong>Manual</strong> and purple <strong>Both</strong>. Since 0.1.22, automatic standard attributes and Light values are included too.</p><p>Each row shows the name, entity ID, attribute where applicable, current value and MQTT topic. The last successful broker acknowledgement includes the time and sent value; unconfirmed values are marked and errors appear separately in red. Acknowledgement proves broker acceptance, not processing by ioBroker or a target device. The open popup refreshes every three seconds and via <strong>Refresh</strong>. The overview covers the running connection and resets when it restarts. Credentials and settings are neither changed nor displayed in this list. Tested locally with manual/label selections, attributes, acknowledgement failures and mobile layout. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.21" target="_blank" rel="noreferrer">Release 0.1.21</a></p><p><strong>0.1.20:</strong> Connection settings are collapsible under <strong>Zugangsdaten</strong> (Credentials). The section stays open for initial setup. With a saved broker address, it automatically collapses after loading and successfully saving. Click its title to reopen it. Save and error messages remain visible; settings and credentials are preserved. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.20" target="_blank" rel="noreferrer">Release 0.1.20</a></p><p><strong>0.1.19</strong> also separates the lines in the transmission list: the name appears above the state, selected-attribute and return-command summary. <strong>Edit</strong> remains on the right. This view was also checked locally at widths of 1300 and 390 pixels. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.19" target="_blank" rel="noreferrer">Release 0.1.19</a></p><p>Since <strong>0.1.18</strong>, device popup rows separate the <strong>name</strong> on the first line, <strong>entity ID</strong> on the second, and <strong>target type with attribute count</strong> on the third. Long names and IDs wrap; the current state remains on the right. This separation is preserved after selection changes. The layout was checked locally at widths of 1300 and 390 pixels. Settings, credentials and selected transmissions are preserved during the update. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.18" target="_blank" rel="noreferrer">Release 0.1.18</a></p><p>MQTT-Client sends selected Home Assistant devices, states and attributes to an external MQTT broker, such as ioBroker&#39;s MQTT adapter. Choose the values you need instead of mirroring the entire HA inventory. The existing HA broker remains in place. The app reads HA directly; it is not a broker bridge.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/mqtt_client" target="_blank" rel="noreferrer">Source and configuration reference</a> · <a href="/projects/mqtt-client/">Deutsche Dokumentation</a></p><h2 id="setup-and-selection" tabindex="-1">Setup and selection <a class="header-anchor" href="#setup-and-selection" aria-label="Permalink to &quot;Setup and selection&quot;">​</a></h2><ol><li>Add <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> to the Home Assistant app store.</li><li>Install and start <strong>MQTT-Client</strong>; amd64 and aarch64 are supported.</li><li>Open the web interface and save the external broker&#39;s host, port, username and password. The default port without TLS is 1883.</li><li>Select a device on the left. Its dialog groups entities into control, sensors, configuration and diagnostics. Search also finds entities inside devices.</li><li>Select the states and attributes to transfer. The checkbox on the right of a value row includes the state and all attributes; device-wide selection can include every value of that device.</li></ol><p>Changes apply immediately. No additional HA access token is required: the app uses Supervisor access to the HA Core API. Use different client IDs and topic prefixes for multiple instances.</p><h2 id="weiterleitung-per-label" tabindex="-1">Forward states using a Home Assistant label <a class="header-anchor" href="#weiterleitung-per-label" aria-label="Permalink to &quot;Forward states using a Home Assistant label {#weiterleitung-per-label}&quot;">​</a></h2><p><img src="`+t+'" alt="Home Assistant dialog for creating a new label"></p><p><em>Home Assistant example: the label is named “zu mqtt client”. Enter the ID of the label you created in the MQTT Client.</em></p><ol><li><strong>Create the label:</strong> In Home Assistant, go to <strong>Settings → Areas, labels &amp; zones → Labels</strong> and create <strong>zu mqtt client</strong>, as shown.</li><li><strong>Look up the label ID:</strong> Open <strong>Settings → Tools → Template</strong> (<strong>Developer tools → Template</strong> in older versions). Paste the template below and copy the result, for example <code>zu_mqtt_client</code>.</li><li><strong>Enter the ID in MQTT Client:</strong> Open <strong>MQTT-Client</strong> from the Home Assistant sidebar. Expand <strong>Übertragung und TLS</strong> (Transfer and TLS). Paste the result into <strong>HA-Label-ID für Zustandsweiterleitung</strong>, directly below <strong>Topic-Präfix</strong>, and click <strong>Speichern und verbinden</strong> (Save and connect).</li><li><strong>Assign the label:</strong> Open <strong>Settings → Devices &amp; services → Entities</strong>, select the entity, and open its settings using the gear icon. Choose <strong>Add label → zu mqtt client</strong> and click <strong>Update</strong>.</li></ol><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">label_id</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zu mqtt client&quot;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><a href="https://www.home-assistant.io/template-functions/label_id/" target="_blank" rel="noreferrer">Home Assistant · label_id</a></p><p>The client checks assignments at the configured polling interval. The label forwards the state and standard metadata and enables supported return channels. Other attributes remain manually selectable. Removing the label stops automatic forwarding and revokes return channels, while manually selected entities remain active. Use retained topic cleanup to remove the last stored MQTT value if needed.</p><p>Tested on Home Assistant <code>.177</code> with a separate MQTT broker. After adding the label, the broker received <code>off</code> and <code>on</code>. After removing it, the next state change was no longer sent. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.17" target="_blank" rel="noreferrer">Release 0.1.17</a></p><h2 id="live-transfer-and-status" tabindex="-1">Live transfer and status <a class="header-anchor" href="#live-transfer-and-status" aria-label="Permalink to &quot;Live transfer and status&quot;">​</a></h2><p>After a complete initial snapshot, the app processes HA state changes live over WebSocket. Reconnecting to HA loads a fresh snapshot; reconnecting to MQTT republishes all selected values.</p><p>If the live connection fails, the existing polling mechanism remains the fallback: <strong>every five seconds by default</strong>, configurable using <code>poll_interval</code> from 1 to 300 seconds. Changes missed during an outage or between fallback polls cannot be reconstructed. Event queue overload is reported and requests a new synchronization.</p><p>Status separates MQTT connectivity and HA reachability and shows live/polling mode, last synchronization, last publication, publication count and sanitized error types. Credentials and message contents are not exposed there.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>MQTT topic</th><th>Contents</th></tr></thead><tbody><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/state</code></td><td>State as text</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/attribute/&lt;attribute&gt;</code></td><td>Selected attribute</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/set</code></td><td>Return channel for supported commands</td></tr><tr><td><code>&lt;topic_prefix&gt;/availability</code></td><td><code>online</code> after successful HA synchronization, otherwise <code>offline</code></td></tr></tbody></table></div><p>The default prefix is <code>ha_external</code>. States and attributes use QoS 1 and Retain; no MQTT Discovery is generated. Initial setup publishes states and attributes before subscribing to <code>/set</code> return channels, with a default 50 ms delay between publications. <code>unknown</code> and <code>unavailable</code> pass through; missing entities produce <code>unavailable</code>.</p><h2 id="commands-back-to-ha" tabindex="-1">Commands back to HA <a class="header-anchor" href="#commands-back-to-ha" aria-label="Permalink to &quot;Commands back to HA&quot;">​</a></h2><p>Return channels are enabled automatically for selected controllable entities. Sensors remain outgoing-only. Send commands to the corresponding <code>/set</code> topic <strong>without Retain</strong>.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Entity</th><th>Payload</th></tr></thead><tbody><tr><td>Toggle-like entity</td><td><code>ON</code> or <code>OFF</code></td></tr><tr><td><code>number</code>, <code>input_number</code></td><td>Numeric value</td></tr><tr><td><code>select</code>, <code>input_select</code></td><td>Available option name</td></tr><tr><td><code>text</code>, <code>input_text</code></td><td>Text</td></tr><tr><td><code>button</code>, <code>input_button</code></td><td><code>PRESS</code></td></tr><tr><td><code>cover</code></td><td><code>OPEN</code>, <code>CLOSE</code>, <code>STOP</code> or <code>{&quot;position&quot;:45}</code></td></tr><tr><td><code>light</code></td><td><code>{&quot;brightness_pct&quot;:75}</code></td></tr><tr><td><code>fan</code></td><td><code>{&quot;percentage&quot;:50}</code></td></tr></tbody></table></div><p>Each JSON command permits only the named field and a finite number from 0 to 100. The HA device must support the function. Legacy entity-ID topics such as <code>ha_external/switch.plug/set</code> remain valid. Retained commands, stale commands and invalid contents are discarded; arbitrary HA action calls are unsupported.</p><h2 id="remove-obsolete-retained-topics" tabindex="-1">Remove obsolete retained topics <a class="header-anchor" href="#remove-obsolete-retained-topics" aria-label="Permalink to &quot;Remove obsolete retained topics&quot;">​</a></h2><p><strong>Veraltete Retain-Topics prüfen</strong> (review obsolete retained topics) lists recorded topics no longer used after selection, prefix or device name changes. Select topics and confirm removal; at most 100 per operation.</p><p>The app clears only its own acknowledged publications on the currently configured broker. Active and foreign topics are protected. The inventory persists in <code>/data/mqtt-topics.json</code>. Failed removals remain available for retry. There is <strong>no automatic cleanup</strong>. Unrecorded obsolete topics from before this update still require manual broker cleanup.</p><h2 id="back-up-and-restore-settings" tabindex="-1">Back up and restore settings <a class="header-anchor" href="#back-up-and-restore-settings" aria-label="Permalink to &quot;Back up and restore settings&quot;">​</a></h2><p><strong>Einstellungen sichern</strong> (back up settings) downloads JSON containing broker settings, client ID, topic prefix, selection, polling interval, publication delay and custom CA. <strong>Sicherung öffnen</strong> (open backup) validates the file and asks before replacing settings.</p><p>The file contains <strong>no MQTT password, client certificate, private key or HA token</strong>. It is not encrypted. Locally stored credentials and client certificate/key are retained for the same broker. Enter them again when changing to another broker. Retained payloads are excluded; this does not replace a complete HA app backup.</p><h2 id="tls-with-custom-certificates" tabindex="-1">TLS with custom certificates <a class="header-anchor" href="#tls-with-custom-certificates" aria-label="Permalink to &quot;TLS with custom certificates&quot;">​</a></h2><p><strong>Übertragung und TLS</strong> (transfer and TLS) accepts a custom CA, client certificate and private key through PEM file upload or pasted text. Certificate and key must be provided together. Use the broker&#39;s TLS port, often 8883.</p><p>Server certificates and hostnames are always verified using system trust or a custom CA. Blank secret fields keep stored values. To remove them, enable the explicit option <strong>Gespeicherte TLS-Zertifikate und Schlüssel entfernen</strong> (remove stored TLS certificates and keys) and save. Invalid TLS configurations are rejected before changing settings.</p><h2 id="updates-and-compatibility" tabindex="-1">Updates and compatibility <a class="header-anchor" href="#updates-and-compatibility" aria-label="Permalink to &quot;Updates and compatibility&quot;">​</a></h2><p>Existing 0.1.15 settings remain valid: broker credentials, device/attribute selection, client ID, topic prefix, polling interval and publication delay are not rewritten at startup. TLS retains its previous setting; new certificate fields default to empty. Updating does not delete retained data.</p><p>Version 0.1.16 was checked with backend tests, an MQTT broker, a WebSocket counterpart, TLS client certificates, the web interface and Docker startup. Verify the actual HA installation and supported device functions in your own environment.</p>',97)])])}const b=a(i,[["render",o]]);export{m as __pageData,b as default};
